const fs = require('fs');
const content = fs.readFileSync('/app/output/index.html', 'utf8');

function test(name, check) {
  if (!check(content)) {
    console.log('FAIL: ' + name);
  } else {
    console.log('PASS: ' + name);
  }
}

test('tab-top-trending-watchlist', c => c.includes('category-tab'));
